const GENERIC_PLAYBOOK = {
  focus: 'Establish what happened, whether it is expected, and whether it spread.',
  tasks: [
    'Verify the source host identity and its owner',
    'Determine whether the activity is expected for this host',
    'Review enrichment verdicts on the observables',
    'Pivot: search other hosts for the same pattern',
    'Escalate to L2 or resolve with justification',
  ],
  containment: 'Assess case by case.',
};

// ---- classify ----
// Weight decides first; on a tie the more advanced tactic wins, so a
// confirmed C2 channel is never filed under Execution or Defense Evasion
// merely because the sort happened to be unstable.
const TACTIC_PRIORITY = {
  'BYOVD': 9, 'Impact': 8, 'Lateral Movement': 7, 'Exfiltration': 7, 'Command and Control': 6,
  'Credential Access': 5, 'Privilege Escalation': 4, 'Defense Evasion': 3, 'Persistence': 3,
  'Execution': 2, 'Discovery': 1, 'Initial Access': 1,
};

const mitreArr = Array.isArray(d.mitre) ? d.mitre : (d.mitre ? [d.mitre] : []);
const known    = mitreArr.map(t => TECHNIQUES[t]).filter(Boolean);
const primary  = known.sort((a, b) =>
  (b.weight - a.weight) || ((TACTIC_PRIORITY[b.tactic] || 0) - (TACTIC_PRIORITY[a.tactic] || 0))
)[0] || null;
// A confirmed correlated chain overrides weight-based selection. BYOVD outranks
// lateral movement: Ring 0 immediately precedes encryption, whereas a lateral
// login is one step earlier in the chain. If both flags somehow co-occur on one
// event, BYOVD wins.
const byovd    = d.byovd_chain === true;
const lateral  = d.lateral_chain === true && !byovd;
// Left alone, the weight sort would file each chain under whichever half scored
// higher and undersell it. The PAIR is the finding, not either half, so a
// correlated chain gets its own tactic at the top of the priority table.
const tactic   = byovd ? 'BYOVD'
               : lateral ? 'Lateral Movement'
               : (primary ? primary.tactic : 'Uncategorised');

// Tactic playbook is the default; a technique may override it when the
// tactic-level plan doesn't fit the specific behavior. Process Injection
// under Defense Evasion is the clearest case: "restore the control" tasks
// are meaningless for in-memory execution — the plan must work the memory
// and the parent instead. The override is keyed on the winning technique,
// so a detection where C2 outranks injection still gets the C2 playbook.
const basePlaybook = PLAYBOOKS[tactic] || GENERIC_PLAYBOOK;
// A correlated chain outranks any per-technique override: the chain playbook is
// the plan, not the plan of either half on its own.
const playbook = byovd ? PLAYBOOKS['BYOVD']
               : lateral ? PLAYBOOKS['Lateral Movement']
               : ((primary && primary.playbook_override) || basePlaybook);

// ---- severity: rule level, raised by tactic weight and threat intel ----
// The tactic bump applies only to rules that are already high-confidence
// (level >= 12). A first-callback suspicion and a confirmed beacon must not
// land on the analyst's queue at the same priority.
const lvl = d.rule_level || 0;
let base = lvl >= 13 ? 3 : lvl >= 10 ? 2 : lvl >= 7 ? 1 : 0;
if (primary && primary.weight === 3 && lvl >= 12) base = Math.min(3, base + 1);
// A correlated chain is Critical regardless of what the individual rule levels
// were. Two independently-weaker signals in sequence are one strong one.
if (byovd || lateral) base = 3;
if (enr && enr.verdict === 'malicious') base = 3;
else if (enr && enr.verdict === 'suspicious') base = Math.min(3, base + 1);

const SEV = [
  { name: 'Low',      tlp: 'WHITE', sla: 72 },
  { name: 'Medium',   tlp: 'GREEN', sla: 24 },
  { name: 'High',     tlp: 'AMBER', sla: 4  },
  { name: 'Critical', tlp: 'RED',   sla: 1  },
][base];

const slaDue = new Date(now.getTime() + SEV.sla * 3600 * 1000);

// ---- fields ----
// Endpoint detections (EID 1, registry, file) carry no source address — the
// event happened ON the host, it did not come from somewhere. Fall back to the
// agent identity so the ticket always names an asset, and so the dedup key
// stays per-host instead of collapsing every endpoint into one ticket.
// A lateral-movement login is the exception: the acting host is the login's
// SOURCE (data.srcip / lateral_srcip), not the agent that observed it (siem).
const agentName = (d.agent && (d.agent.name || d.agent.id)) || d.agent_name || null;
const srcIp = d.lateral_srcip
  || (d.soar_decision && d.soar_decision.src_ip)
  || (d.data && (d.data.srcip || d.data.src_ip))
  || agentName
  || 'unknown';
const dstDom = d.parent_domain || (d.data && d.data.parent_domain) || null;
const qCount = d.query_count || (d.data && d.data.query_count) || null;
const action = (d.soar_decision && d.soar_decision.action) || 'none';
const reason = (d.soar_decision && d.soar_decision.reason) || 'n/a';

// ---- identifiers + dedup ----
// The ticket key doubles as TheHive's sourceRef. Identical detections
// (same rule, same source, same destination) inside one window resolve to
// the same key, so TheHive rejects the duplicate and the open ticket stands.
const DEDUP_WINDOW_MS = 15 * 60 * 1000;
const dateKey = `${now.getUTCFullYear()}${pad(now.getUTCMonth() + 1)}${pad(now.getUTCDate())}`;
const bucket  = Math.floor(now.getTime() / DEDUP_WINDOW_MS);
const dstEp   = (d.data && (d.data.destinationIp || d.data.dst_ip))
  ? `${d.data.destinationIp || d.data.dst_ip}-${d.data.destinationPort || d.data.dst_port || 'x'}`
  : (dstDom || 'nodst');
// A correlated chain gets its own key space. Without this the chain ticket
// collides with the plain single-rule ticket already opened in the same window,
// TheHive rejects it as a duplicate, and the most important ticket is lost
// silently.
const chainTag  = byovd ? 'BYOVD-' : lateral ? 'LATERAL-' : '';
const ticketKey = `SOC-${dateKey}-b${bucket}-${chainTag}${d.rule_id || 'x'}-${srcIp}-${dstEp}`;

// ---- containment ----
// The alias PATCH returning 200 only means the list was updated — it does not
// mean traffic is blocked. No firewall rule consumes soar_blocklist yet, so the
// alias never reaches the packet filter. Claiming containment the SOAR has not
// achieved is worse than not containing at all: the analyst stops responding.
// Flip this to true once a LAN block rule sources the alias.
const CONTAINMENT_ENFORCED = false;
const contained = action === 'allow_block' && CONTAINMENT_ENFORCED;

const CONTAINMENT_NOTE = {
  allow_block: CONTAINMENT_ENFORCED
    ? `Host ${srcIp} isolated automatically (added to pfSense soar_blocklist).`
    : `Host ${srcIp} was added to the pfSense soar_blocklist alias, but no firewall rule consumes that alias yet — traffic is NOT blocked. Manual containment required.`,
  refused: `No automated containment — ${srcIp} is protected infrastructure. Manual assessment required before any action.`,
  skip: agentName
    ? `No automated containment — this is a host-based detection on ${agentName} with no network source to block. Endpoint-level containment required.`
    : `No automated containment — the alert carried no source address to act on.`,
  none: `No containment attempted.`,
};
const actionText = CONTAINMENT_NOTE[action] || CONTAINMENT_NOTE.none;

// ---- threat intelligence summary line ----
const tiLine = !enr ? 'Enrichment unavailable.'
  : enr.status === 'skipped' ? 'No external observables to enrich.'
  : enr.verdict === 'malicious' ? `Threat intelligence flags an observable as malicious: ${(enr.verdict_reason || []).join('; ')}`
  : enr.verdict === 'suspicious' ? `Threat intelligence raised suspicion: ${(enr.verdict_reason || []).join('; ')}`
  : 'No adverse threat-intelligence findings on the observables.';

// ---- description ----
const assessmentLine = byovd
  ? `kernel driver loaded from a user-writable path, then security tooling terminated ${d.byovd_gap_seconds}s later`
  : lateral
    ? `${d.lateral_prior_desc || 'a high-severity alert'} on ${d.lateral_srcip}, then an unauthorized SSH login to the SIEM as ${d.lateral_user || 'a service account'} ${d.lateral_gap_seconds}s later`
    : (primary ? primary.name : (d.rule_desc || 'uncategorised activity'));

const description = `
## Assessment
**${tactic}** — ${assessmentLine}.
${playbook.focus}

Containment: **${contained ? 'APPLIED' : 'NOT APPLIED'}**. ${tiLine}

## Detection
| Field | Value |
|---|---|
| Rule | ${d.rule_id} — ${d.rule_desc} |
| Wazuh level | ${lvl} |
| Tactic | ${tactic} |
| Technique | ${mitreArr.join(', ') || 'n/a'} |
| Source host | \`${srcIp}\` |
${dstDom ? `| Destination | \`${dstDom}\` |\n` : ''}${qCount ? `| Observed count | ${qCount} |\n` : ''}| Detected | ${d.timestamp || now.toISOString()} |

${byovd ? `
## Correlated chain
| Step | Evidence |
|---|---|
| 1. Driver loaded | \`${d.byovd_driver || 'unknown'}\` |
| 2. Security tooling terminated | \`${d.byovd_killed || 'unknown'}\` |
| Gap between them | ${d.byovd_gap_seconds}s |

Neither half is conclusive alone. A kernel driver load from a user-writable
path can be benign; a security process ending can be an update. Together, on
one host, seconds apart, they are the BYOVD sequence - and this holds for
driver variants nobody has catalogued yet, because the signal is the ORDER,
not the driver.
` : ''}${lateral ? `
## Correlated chain
| Step | Evidence |
|---|---|
| 1. Prior host activity | rule ${d.lateral_prior_rule} (level ${d.lateral_prior_level}) — ${d.lateral_prior_desc} |
| 2. Unauthorized SIEM login | \`${d.lateral_user}\` from \`${d.lateral_srcip}\` |
| Gap between them | ${d.lateral_gap_seconds}s |

The login alone says only "an unexpected source authenticated". Paired with a
high-severity alert from that SAME host moments earlier, it is lateral movement:
the box that just ran a beacon then logged into the SIEM. The valid key is not
the signal — the unexpected source, arriving right after that host lit up, is.
The displayed source may itself be a pivot; verify the true origin off-host.
` : ''}
## Response taken
${actionText}

## Recommended containment for this tactic
${playbook.containment}
`.trim();

// ---- observables ----
const observables = [
  { type: 'ip', value: srcIp, role: 'source', ioc: false, note: 'internal endpoint' },
];
if (dstDom) {
  observables.push({
    type: 'domain', value: dstDom, role: 'destination',
    ioc: !!(enr && (enr.verdict === 'malicious' || enr.verdict === 'suspicious')),
    note: enr && enr.virustotal && enr.virustotal.detections
      ? `VirusTotal: ${enr.virustotal.detections}` : 'no enrichment data',
  });
}

// ---- investigation plan ----
// The containment decision shapes the first step: infrastructure needs
// authorisation, a host-based detection needs the host confirmed rather than
// hunted for, and everything else goes straight to the tactic playbook.
const leadTasks =
  action === 'refused'
    ? ['Assess impact on the protected asset before any containment decision',
       'Escalate to L2 — containment on infrastructure requires authorisation']
    : action === 'skip'
      ? (agentName
          ? [`Confirm the activity on ${agentName} — host-based detection, no network source to trace`]
          : ['Identify the affected host from the raw alert — no source address was present'])
      : [];

const investigationTasks = [...leadTasks, ...playbook.tasks]
  .map((t, i) => ({ id: i + 1, task: t, status: 'todo', owner: 'L1' }));

// ---- ticket ----
const ticket = {
  ticket_key:  ticketKey,
  summary:     byovd
    ? `[${SEV.name}] BYOVD: driver load followed by security-tooling termination on ${srcIp} (${d.byovd_gap_seconds}s apart)`
    : lateral
      ? `[${SEV.name}] Lateral Movement: ${d.lateral_srcip} logged into the SIEM as ${d.lateral_user} ${d.lateral_gap_seconds}s after rule ${d.lateral_prior_rule}`
      : `[${SEV.name}] ${tactic}: ${primary ? primary.name : (d.rule_desc || 'Security alert')} on ${srcIp}`,
  type:        'Security Incident',
  status:      'Open',
  priority:    SEV.name,
  tlp:         SEV.tlp,
  created_utc: now.toISOString(),
  reporter:    'Wazuh SOAR (automated)',
  assignee:    'unassigned',
  sla_due_utc: slaDue.toISOString(),
  sla_hours:   SEV.sla,

  dedup: {
    window_minutes: DEDUP_WINDOW_MS / 60000,
    key: ticketKey,
    note: 'Repeat detections of this exact activity within the window fold into this ticket.',
  },

  classification: {
    tactic,
    techniques: mitreArr,
    technique_names: known.map(k => k.name),
    confidence: (byovd || lateral) ? 'correlated chain' : (known.length ? 'mapped' : 'unmapped — rule carries no known technique'),
    ...(byovd ? {
      chain: {
        driver_loaded: d.byovd_driver,
        process_terminated: d.byovd_killed,
        gap_seconds: d.byovd_gap_seconds,
        correlated_by: 'SOAR (the rule engine cannot chain events of different kinds)',
      },
    } : {}),
    ...(lateral ? {
      chain: {
        prior_rule: d.lateral_prior_rule,
        prior_level: d.lateral_prior_level,
        prior_desc: d.lateral_prior_desc,
        source_host: d.lateral_srcip,
        account: d.lateral_user,
        gap_seconds: d.lateral_gap_seconds,
        correlated_by: 'SOAR (cross-host: the login is observed on siem, the prior alert on the source host)',
      },
    } : {}),
  },

  labels: [
    ...mitreArr,
    tactic.toLowerCase().replace(/\s+/g, '-'),
    SEV.name.toLowerCase(),
    contained ? 'auto-contained' : 'not-contained',
    ...(byovd ? ['byovd', 'correlated-chain'] : []),
    ...(lateral ? ['lateral-movement', 'correlated-chain'] : []),
    ...(enr && enr.verdict && enr.verdict !== 'info' ? [`ti-${enr.verdict}`] : []),
  ],

  description,
  observables,

  timeline: [
    { time: d.timestamp || now.toISOString(), event: `Detection: ${d.rule_id} — ${d.rule_desc}` },
    ...(byovd ? [{ time: now.toISOString(),
      event: `Correlated: driver ${d.byovd_driver} loaded, ${d.byovd_killed} terminated ${d.byovd_gap_seconds}s later` }] : []),
    ...(lateral ? [{ time: now.toISOString(),
      event: `Correlated: ${d.lateral_srcip} triggered rule ${d.lateral_prior_rule} (level ${d.lateral_prior_level}) ${d.lateral_gap_seconds}s before this login` }] : []),
    { time: now.toISOString(), event: `Classified as ${tactic}` },
    { time: now.toISOString(), event: `SOAR decision: ${action} (${reason})` },
    ...(enr && enr.status === 'completed'
      ? [{ time: now.toISOString(), event: `Enrichment complete — verdict ${enr.verdict}` }] : []),
  ],

  automated_response: {
    decision: action,
    reason,
    action_taken: actionText,
    contained,
    enforcement_verified: CONTAINMENT_ENFORCED,
    allowlist_protected: action === 'refused' && reason === 'allowlist',
  },

  enrichment: enr ? {
    status: enr.status,
    verdict: enr.verdict,
    reasons: enr.verdict_reason,
    virustotal: enr.virustotal,
    abuseipdb: enr.abuseipdb,
    observables: enr.observables,
    skipped: enr.skipped,
    analyzers: { run: enr.analyzers_run, failed: enr.analyzers_failed },
    took_ms: enr.duration_ms,
  } : { status: 'unavailable', note: 'No enrichment ran for this alert' },

  investigation_tasks: investigationTasks,

  work_notes: [],
  disposition: 'PENDING',
  resolution: '',

  playbook: `PICERL — ${tactic}: Prepare → Identify → Contain (${contained ? 'automated' : 'manual required'}) → Eradicate → Recover → Lessons`,
  runbook_url: 'https://github.com/AJahmadcyber/homelab-mdr',
};

return [{ json: ticket }];

// Extract source IP from the Wazuh alert + allowlist safety check
const alert = $('Webhook').first().json.body;

// pull src_ip from common Wazuh alert locations
const srcIp = alert?.data?.src_ip 
           || alert?.data?.srcip 
           || alert?.data?.win?.eventdata?.sourceIp 
           || null;

// --- SAFETY: infrastructure allowlist (NEVER block these) ---
const ALLOWLIST = {
  "10.10.10.1":  "pfSense gateway",
  "10.10.10.10": "siem (SIEM + n8n)",
  "10.10.10.2":  "ThinkPad host"
};

let decision;
if (!srcIp) {
  decision = { action: "skip", reason: "no_src_ip", src_ip: null };
} else if (ALLOWLIST[srcIp]) {
  decision = { action: "refused", reason: "allowlist", src_ip: srcIp, detail: ALLOWLIST[srcIp] };
} else {
  decision = { action: "allow_block", reason: "passed_safety", src_ip: srcIp };
}

return [{
  json: {
    ...alert,
    soar_decision: decision,
    rule_id: alert?.rule?.id,
    rule_level: alert?.rule?.level,
    rule_desc: alert?.rule?.description,
    mitre: alert?.rule?.mitre?.id
  }
}];

// Maps the SOC ticket to a TheHive v1 Alert payload
const t = $('SOC Investigation Ticket').first().json;
const d = $('allowlist').first().json;

const SEV_MAP = { low: 1, medium: 2, high: 3, critical: 4 };
const severity = SEV_MAP[String(t.priority || '').toLowerCase()] || 2;

const TLP_MAP = { clear: 0, white: 0, green: 1, amber: 2, 'amber+strict': 3, red: 4 };
let tlp = 2;
if (typeof t.tlp === 'number') tlp = t.tlp;
else if (t.tlp) { const k = String(t.tlp).toLowerCase().replace('tlp:', ''); if (k in TLP_MAP) tlp = TLP_MAP[k]; }

const checklist = (t.investigation_tasks || []).map(x => `- [ ] ${x.task}`).join('\n');
const timeline  = (t.timeline  || []).map(ev => `- ${ev.time} — ${ev.event}`).join('\n');
const e = t.enrichment || {};

const description = [
  t.description || '',
  `**Playbook:** ${t.playbook}`,
  `**SLA:** ${t.sla_hours}h — due ${t.sla_due_utc}`,
  `### Classification`,
  `Tactic: **${t.classification.tactic}** | Techniques: ${(t.classification.techniques || []).join(', ') || '—'} (${t.classification.confidence})`,
  `### Automated response`,
  `Decision: **${t.automated_response.decision}** (${t.automated_response.reason}) — ${t.automated_response.action_taken} | contained: ${t.automated_response.contained}`,
  `### Enrichment`,
  `Status: ${e.status} | Verdict: **${e.verdict || 'n/a'}**${e.reasons ? ' — ' + [].concat(e.reasons).join('; ') : ''}`,
  `### L1 investigation checklist`,
  checklist,
  `### Timeline`,
  timeline,
].join('\n\n');

const observables = (t.observables || [])
  .filter(o => o && o.value)
  .map(o => ({
    dataType: o.type,
    data: String(o.value),
    message: `${o.role || ''}${o.note ? ' — ' + o.note : ''}`,
    ioc: !!o.ioc,
    tags: o.role ? ['role:' + o.role] : [],
  }));

return [{ json: {
  type: 'soar-triage',
  source: 'wazuh-soar',
  sourceRef: t.ticket_key,
  title: t.summary,
  description,
  severity,
  tlp,
  date: Date.parse(t.created_utc) || Date.now(),
  tags: [...(t.labels || []), 'rule-' + (d.rule_id || 'unknown')],
  observables,
} }];

// ============================================================
//  BYOVD correlation (Phase 7, Stage 4d)
//
//  Links two atomic detections that Wazuh reports independently:
//    100341 - kernel driver loaded from a user-writable path
//    100370 - security tooling terminated
//
//  Either alone is inconclusive. Together, inside a short window on the same
//  host, they are the BYOVD shape ESET named as the strongest signal against
//  GentleKiller - and it holds across all 8 variants because it keys on the
//  SEQUENCE, not on driver identity.
//
//  Why this lives here and not in the rule engine: Wazuh's if_matched_* family
//  is built for repetition patterns (repeated auth failures), not for chaining
//  events of different kinds. Five attempts inside the engine either loaded and
//  never fired, were rejected by analysisd, or broke the atomic rules by
//  winning sibling precedence. The atomic detections stay in Wazuh; the link
//  is made here, where the logic is explicit and testable.
//
//  Placed between "Cortex enrichment" and "If1" so the enrichment survives and
//  both the containment decision and the ticket builder see the raised level.
// ============================================================

const d = $input.first().json;

const DRIVER_LOAD_RULE = '100341';
const SEC_KILL_RULE    = '100370';
const WINDOW_MS        = 5 * 60 * 1000;

// Workflow-scoped storage: n8n code nodes are stateless between executions, so
// the driver-load event has to be remembered somewhere for the kill event to
// find it. Note this only persists on real (triggered) executions - manual
// "Execute workflow" runs do not write it.
const store = $getWorkflowStaticData('global');
if (!store.byovd) store.byovd = {};

const host = (d.agent && (d.agent.name || d.agent.id)) || d.agent_name || 'unknown';
const rid  = String(d.rule_id || (d.rule && d.rule.id) || '');
const now  = Date.now();

// Prune expired entries so the store cannot grow without bound - it is
// persisted in n8n's database, not just in memory.
for (const h of Object.keys(store.byovd)) {
  if (now - store.byovd[h].ts > WINDOW_MS) delete store.byovd[h];
}

// --- half 1: remember the driver load ---
if (rid === DRIVER_LOAD_RULE) {
  const img =
    (d.data && d.data.win && d.data.win.eventdata && d.data.win.eventdata.imageLoaded) ||
    (d.win && d.win.eventdata && d.win.eventdata.imageLoaded) ||
    'unknown';
  store.byovd[host] = { ts: now, image: String(img).replace(/\\\\/g, '\\') };
  return [{ json: { ...d, byovd_chain: false } }];
}

// --- half 2: a kill arrives - was there a load just before it? ---
if (rid === SEC_KILL_RULE) {
  const prior = store.byovd[host];
  if (prior && (now - prior.ts) <= WINDOW_MS) {
    const gap = Math.round((now - prior.ts) / 1000);
    const killed =
      (d.data && d.data.win && d.data.win.eventdata && d.data.win.eventdata.image) ||
      'a security process';

    // The pair is worth more than either half: raise it to the top severity and
    // re-tag it so the ticket is filed as BYOVD, not as an isolated kill.
    return [{ json: {
      ...d,
      byovd_chain: true,
      byovd_driver: prior.image,
      byovd_killed: String(killed).replace(/\\\\/g, '\\'),
      byovd_gap_seconds: gap,
      rule_level: 15,
      mitre: ['T1068', 'T1562.001', 'T1543.003'],
      rule_desc: `BYOVD chain on ${host}: driver loaded from ${prior.image}, then security tooling terminated ${gap}s later`,
    }}];
  }
}

// Everything else passes through untouched.
return [{ json: { ...d, byovd_chain: false } }];

// ============================================================
//  Lateral Movement correlation (Phase 7, Stage 5 / 7-E)
//
//  Links an unauthorized SIEM login to prior high-severity activity on the
//  SAME source host, turning orphan tickets into one lateral-movement incident.
//
//    Remembered:  any alert at level >= 12 whose agent.ip is the acting host
//                 (e.g. 92213 beacon drop, 92910 injection on win-ep)
//    Trigger:     100210 - unauthorized SSH publickey login to the SIEM
//
//  Join key (confirmed by payload probe):
//    login event:  agent.ip = 10.10.10.10 (siem-self, where sshd logged it)
//                  data.srcip = 10.10.10.20 (the ACTUAL source host)
//    host alert:   agent.ip = 10.10.10.20 (win-ep, where it was observed)
//    => match  login.data.srcip  ==  host_alert.agent.ip
//  The pivot through win-ep is precisely what makes the two line up: sshd sees
//  the login coming from win-ep's IP, which is win-ep's own agent.ip.
//
//  Store, not a Wazuh query: the gate passes every level>=10 alert through this
//  workflow, so a host's beacon/injection arrives here first and is remembered.
//  When the login arrives it just looks back. Same pattern as BYOVD correlation.
//  Caveat (inherited): $getWorkflowStaticData persists only on REAL triggered
//  executions, not on manual "Execute workflow" runs.
//
//  Placed after BYOVD correlation, before If1, so enrichment survives and the
//  raised level reaches both the containment decision and the ticket builder.
// ============================================================

const d = $input.first().json;

const LOGIN_RULE = '100210';       // unauthorized SIEM login (trigger)
const MEM_LEVEL  = 12;             // remember host alerts at or above this
const WINDOW_MS  = 15 * 60 * 1000; // 15-minute correlation window

const store = $getWorkflowStaticData('global');
if (!store.lateral) store.lateral = {};

// Field access - probe confirmed both nested and flat forms may be present.
const rid       = String((d.rule && d.rule.id) || d.rule_id || '');
const level      = Number((d.rule && d.rule.level) || d.rule_level || 0);
const agentIp    = (d.agent && d.agent.ip) || null;
const agentName  = (d.agent && d.agent.name) || 'unknown';
const desc       = (d.rule && d.rule.description) || d.rule_desc || '';
const now        = Date.now();

// Prune expired host entries so the store stays bounded.
for (const ip of Object.keys(store.lateral)) {
  if (now - store.lateral[ip].ts > WINDOW_MS) delete store.lateral[ip];
}

// --- half 1: remember a high-sev alert, keyed by the observing host's IP ---
// Skip the login rule itself: it is observed on siem (agent.ip 10.10.10.10),
// not on the source host, and must never seed its own correlation.
if (rid !== LOGIN_RULE && level >= MEM_LEVEL && agentIp) {
  store.lateral[agentIp] = {
    ts: now,
    host: agentName,
    rule_id: rid,
    level: level,
    desc: String(desc),
  };
  return [{ json: { ...d, lateral_chain: false } }];
}

// --- half 2: the unauthorized login arrives - any recent host activity? ---
if (rid === LOGIN_RULE) {
  const srcip = (d.data && d.data.srcip) || null;
  const prior = srcip ? store.lateral[srcip] : null;

  if (prior && (now - prior.ts) <= WINDOW_MS) {
    const gap  = Math.round((now - prior.ts) / 1000);
    const user = (d.data && d.data.dstuser) || 'a service account';

    // The pair is the finding: raise to critical, re-tag as lateral movement,
    // carry the linked alert so the ticket shows the chain, not one event.
    return [{ json: {
      ...d,
      lateral_chain: true,
      lateral_srcip: srcip,
      lateral_user: String(user),
      lateral_prior_rule: prior.rule_id,
      lateral_prior_level: prior.level,
      lateral_prior_desc: prior.desc,
      lateral_gap_seconds: gap,
      rule_level: 15,
      mitre: ['T1078', 'T1021.004'],
      rule_desc: `Lateral movement to SIEM: ${prior.host} (${srcip}) triggered rule ${prior.rule_id} (level ${prior.level}) ${gap}s before an unauthorized SSH login as ${user}`,
    }}];
  }

  // Login with no recent host activity in-window: still unauthorized, but no
  // chain context. Pass through unchanged - the base 100210 ticket stands.
  return [{ json: { ...d, lateral_chain: false } }];
}

// Everything else passes through untouched.
return [{ json: { ...d, lateral_chain: false } }];
